CREATE TABLE "article_revisions" ("id" TEXT NOT NULL, "articleId" TEXT NOT NULL, "revisionNumber" INTEGER NOT NULL, "title" TEXT NOT NULL, "summary" TEXT, "content" TEXT NOT NULL, "status" "ArticleStatus" NOT NULL, "editorId" TEXT NOT NULL, "changeNote" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "article_revisions_pkey" PRIMARY KEY ("id"));
CREATE TABLE "audit_events" ("id" TEXT NOT NULL, "action" "AuditAction" NOT NULL, "details" TEXT, "actorId" TEXT, "articleId" TEXT, "ipAddress" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "audit_events_pkey" PRIMARY KEY ("id"));
